}

// Fonction de comparaison pour trier par ordre alphabétique des noms
function compareName(a, b) {
  var nameA = a.name.toLowerCase();
  var nameB = b.name.toLowerCase();
  if (nameA < nameB) return -1;
  if (nameA > nameB) return 1;
  return 0;
}

// Trier l'array par ordre alphabétique des noms des capteurs en utilisant la fonction de comparaison
