// recherche récursive d’un champ dans tout l’objet
function deepSearch(obj, synonyms) {
    if (!obj || typeof obj !== "object") return null;

    for (const key of Object.keys(obj)) {
        const value = obj[key];

        // match clé
        if (synonyms.includes(key)) {
            if (value !== null && value !== undefined && value !== "") {
                return value;
            }
        }

        // descente récursive
        if (typeof value === "object") {
            const found = deepSearch(value, synonyms);
            if (found) return found;
        }
    }
    return null;
}

