// Parser SONAR
//
// - Lit le device dans apps[appId].devices[deviceId]
// - Port 1 : distances dans les bytes -> value1, value2, ...
// - Port 10 : 4 bytes, les 2 derniers = batterie en mV
// - Pour les metrics sonar : min=0, max=100, unity=null, alertOn=false, lastAlert=0
// - Pour sonar : batteryTreshold = 2800 (mV) si non défini

const appId    = msg.appId;
const deviceId = msg.devId;
const ttn      = msg.ttn;
const uplink = ttn.uplink_message;
const fPort = uplink.f_port;

let apps = global.get("apps", "file") || {};
let dev = apps[appId].devices[deviceId];


// Seuil batterie sonar
if (dev.meta.batteryTreshold == null) {
    dev.meta.batteryTreshold = 2800;
}

// ---------------------------------------------------------------
// 3) Récupération des bytes (pour ports 1 et 10)
// ---------------------------------------------------------------
let bytes = null;

// Priorité : decoded_payload.bytes
if (Array.isArray(uplink.decoded_payload?.bytes)) {
    bytes = uplink.decoded_payload.bytes;
} else if (typeof uplink.frm_payload === "string") {
    try {
        const buf = Buffer.from(uplink.frm_payload, "base64");
        bytes = Array.from(buf);
    } catch (e) {
        node.warn(`Parser SONAR : impossible de décoder frm_payload base64 pour "${deviceId}".`);
        bytes = null;
    }
}

// Message de base
let message = {
    deviceId: deviceId,
    rssi: dev.meta.rssi ?? null,
    snr: dev.meta.snr ?? null,
    port: fPort
};

// ---------------------------------------------------------------
// 4) Si PORT 1 : valeurs sonar (distance, etc.)
// ---------------------------------------------------------------
if (fPort === 1) {

    if (!Array.isArray(bytes) || bytes.length < 2) {
        node.warn(
            `Parser SONAR (port 1) : aucun byte exploitable (len=${bytes ? bytes.length : "null"}) pour "${deviceId}".`
        );
        // On renvoie quand même le message minimal
        apps[appId].devices[deviceId] = dev;
        flow.set("apps", apps, "file");
        msg.payload = message;
        return msg;
    }

    const numPairs = Math.floor(bytes.length / 2);
    if (numPairs === 0) {
        node.warn(
            `Parser SONAR (port 1) : len=${bytes.length} (impair), aucune paire complète pour "${deviceId}".`
        );
    }

    for (let i = 0; i < numPairs; i++) {
        const hi = bytes[2 * i];
        const lo = bytes[2 * i + 1];

        const value = (hi << 8) + lo;   // 16 bits non signé
        const key = `value${i + 1}`;  // value1, value2, ...

        // Ajout au payload de sortie
        message[key] = value;

        // S’assurer que la metric existe
        if (!dev.metrics[key]) {
            dev.metrics[key] = {
                value: null,
                min: 0,
                max: 100,
                unity: null,
                alertOn: false,
                lastAlert: 0
            };
        }

        // Mise à jour de la valeur
        dev.metrics[key].value = value;
    }

    if (bytes.length % 2 === 1) {
        node.warn(
            `Parser SONAR (port 1) : longueur impaire (${bytes.length}) pour "${deviceId}", ` +
            `dernier byte ignoré.`
        );
    }
}

// ---------------------------------------------------------------
// 5) Si PORT 10 : batterie (4 bytes, on garde les 2 derniers)
// ---------------------------------------------------------------
if (fPort === 10) {

    if (!Array.isArray(bytes) || bytes.length < 4) {
        node.warn(
            `Parser SONAR (port 10) : besoin de 4 bytes, len=${bytes ? bytes.length : "null"} pour "${deviceId}".`
        );
    } else {
        const hi = bytes[2];
        const lo = bytes[3];
        const bat = (hi << 8) + lo;   // mV

        message.battery = bat;
        dev.meta.battery = bat;

        // S’assurer du seuil batterie sonar
        if (dev.meta.batteryTreshold == null) {
            dev.meta.batteryTreshold = 2800;
        }
    }
}

// ---------------------------------------------------------------
// 6) Sauvegarde et sortie
// ---------------------------------------------------------------
apps[appId].devices[deviceId] = dev;
global.set("apps", apps, "file");

msg.payload = message;

return msg;

