// Convertit une fréquence '1d', '2h', '30m', '1w' en msec.
// Si non valide, on renvoie 1 jour.

function parseFrequencyMs(freqStr) {
    if (!freqStr || typeof freqStr !== 'string') {
        return 24 * 60 * 60 * 1000; // 1 jour par défaut
    }
    const m = freqStr.match(/^(\d+)([mhdw])$/); // minutes, heures, jours, semaines
    if (!m) {
        return 24 * 60 * 60 * 1000;
    }
    const value = Number(m[1]);
    const unit = m[2];

    switch (unit) {
        case 'm': return value * 60 * 1000;
        case 'h': return value * 60 * 60 * 1000;
        case 'd': return value * 24 * 60 * 60 * 1000;
        case 'w': return value * 7 * 24 * 60 * 60 * 1000;
        default: return 24 * 60 * 60 * 1000;
    }
}

// Rend une version lisible de la fréquence 
// ('1d' -> '1 jour', '2h' -> '2 heures', etc.)

function frequencyToHuman(freqStr) {
    if (!freqStr || typeof freqStr !== 'string') {
        return "1 jour";
    }
    const m = freqStr.match(/^(\d+)([mhdw])$/);
    if (!m) {
        return freqStr;
    }
    const value = Number(m[1]);
    const unit = m[2];

    let label = "";
    switch (unit) {
        case 'm':
            label = value > 1 ? "minutes" : "minute";
            break;
        case 'h':
            label = value > 1 ? "heures" : "heure";
            break;
        case 'd':
            label = value > 1 ? "jours" : "jour";
            break;
        case 'w':
            label = value > 1 ? "semaines" : "semaine";
            break;
    }
    return `${value} ${label}`;
}

const now = Date.now();

// --- Logique d'alertes ---
const metrics = dev.metrics;
const deviceName = dev.deviceName ;
let alertLines = [];

for (const [metricName, metric] of Object.entries(metrics)) {
    if (!metric) continue;

    // Si la metric.alertOn n'est pas active, on passe
    if (!metric.alertOn) {
        continue;
    }


    // On regrade ici si on continue ou pas
    let value = metric.value;
    let min = metric.min;
    let max = metric.max;
    let unity = metric.unity;

    if (value === undefined || min === undefined || max === undefined) {
        continue;
    }

    value = Number(value);
    min = Number(min);
    max = Number(max);

    if (isNaN(value) || isNaN(min) || isNaN(max)) {
        continue;
    }

    // Check anti-Spam
    // Anti-spam : fréquence par métrique
    const freqMs = parseFrequencyMs(metric.frequencyAlert || "1d");
    const lastAlert = Number(metric.lastAlert || 0);

    // si on a déjà alerté récemment, on skip cette métrique
    if (lastAlert !== 0 && (now - lastAlert) < freqMs) {
        continue;
    }

    // On regarde d'abord si la valeur est hors des bornes
    let line = null;
    let isAlert = false;
    const freqHuman = frequencyToHuman(metric.frequencyAlert || "1d");

    if (value < min) {
        line = `🔹​ ${metricName} est à ${value} ${unity}, en dessous du seuil min de ${min} ${unity}`
            + `\n (Rappel dans ${freqHuman} si persiste.) \n\n`;
        isAlert = true;
    } else if (value > max) {
        line = `🔹​ ${metricName} est à ${value} ${unity}, au dessus du seuil max de ${max} ${unity}`
            + `\n (Rappel dans ${freqHuman} si persiste.) \n\n`;
        isAlert = true;
    }

    if (!isAlert) {
        continue; // dans la plage, pas d'alerte
    }
    // Rajouter "prochaine message à la ligne"
    // on pousse une ligne dans le msg à envoyer
    alertLines.push(line);

    // On met à jour lastAlert pour cette métrique
    metric.lastAlert = now;
}

// Si au moins une métrique est en alerte, on envoie un message Telegram pour ce device
if (alertLines.length > 0) {
    const text =
