// --- fonctions utilitaires ---
function normalize(str) {
    return String(str || "")
        .trim()
        .normalize("NFD")                     // décompose accents
        .replace(/[\u0300-\u036f]/g, "")      // supprime accents
        .toLowerCase()
        .replace(/\s+/g, "")                  // supprime espaces
        .replace(/-/g, "_");                  // remplace tirets par underscore
}
// identifiant strict (SQL/Grafana/Postgres): [a-z0-9_]
function cleanIdentifier(str) {
    return normalize(str)
        .replace(/[^a-z0-9_]/g, "");
}
msg.tenant = cleanIdentifier(String(msg.appId));

const rxList = Array.isArray(ttn?.uplink_message?.rx_metadata)
    ? ttn.uplink_message.rx_metadata
    : [];

// 1) Max RSSI / Max SNR
let rssiMax = null;
let snrMax  = null;

for (const rx of rxList) {
    if (typeof rx.rssi === "number") {
        if (rssiMax === null || rx.rssi > rssiMax) rssiMax = rx.rssi;
    }
    if (typeof rx.snr === "number") {
        if (snrMax === null || rx.snr > snrMax) snrMax = rx.snr;
    }
}

// 2) Moyenne lat/lon (si dispo)
let latSum = 0;
let lonSum = 0;
let locCount = 0;

for (const rx of rxList) {
    const lat = rx?.location?.latitude;
    const lon = rx?.location?.longitude;
    if (typeof lat === "number" && typeof lon === "number") {
        latSum += lat;
        lonSum += lon;
        locCount++;
    }
}

const latitude  = locCount > 0 ? (latSum / locCount) : null;
const longitude = locCount > 0 ? (lonSum / locCount) : null;

// 3) lastSeen
const lastSeen =
    ttn?.uplink_message?.received_at ||
    ttn?.received_at ||
    null;

// 4) Écriture dans meta
dev.meta.rssi = rssiMax;
dev.meta.snr  = snrMax;
dev.meta.latitude  = latitude;
dev.meta.longitude = longitude;
dev.meta.lastSeen = lastSeen;

